window.docContents[253].resolve({"/#Functional-Programming-in-Lean--Getting-to-Know-Lean--Summary--Evaluating-Expressions":{"contents":"In Lean, computation occurs when expressions are evaluated.\nThis follows the usual rules of mathematical expressions: sub-expressions are replaced by their values following the usual order of operations, until the entire expression has become a value.\nWhen evaluating an if or a match, the expressions in the branches are not evaluated until the value of the condition or the match subject has been found.\n\nOnce they have been given a value, variables never change.\nSimilarly to mathematics but unlike most programming languages, Lean variables are simply placeholders for values, rather than addresses to which new values can be written.\nVariables' values may come from global definitions with def, local definitions with let, as named arguments to functions, or from pattern matching.\n\n","context":"Functional Programming in Lean\u0009Getting to Know Lean\u0009Summary","header":"1.9.1. Evaluating Expressions","id":"/#Functional-Programming-in-Lean--Getting-to-Know-Lean--Summary--Evaluating-Expressions"},"/#Functional-Programming-in-Lean--Introduction--Release-history--December___-2022":{"contents":"This release adds a chapter on applicative functors that additionally describes structures and type classes in more detail.\nThis is accompanied with improvements to the description of monads.\nThe December 2022 release was delayed until January 2023 due to winter holidays.\n\n","context":"Functional Programming in Lean\u0009Introduction\u0009Release history","header":"December, 2022","id":"/#Functional-Programming-in-Lean--Introduction--Release-history--December___-2022"},"/#tactics-induction-proofs":{"contents":"\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Functional Programming in Lean","header":"Interlude: Tactics, Induction, and Proofs","id":"/#tactics-induction-proofs"}});